/* Unified learning curriculum. All existing engines stay available; one main ordered journey. */
(function(){
const curriculum=[["computer","How a computer becomes a server","Infrastructure foundation","Before you learn identity, understand the machine that runs the identity service.","Alex presses the sign-in button on a Windows laptop. A remote service is slow. Which components are involved before identity is even checked?",["hardware","vm","server"],[],[],[],["cpu","ram","process","service","operating-system","virtual-machine"],[["Start with a machine","CPU executes instructions; RAM holds active working data; disk persists data. An OS schedules the process. A service is a program running to answer requests, often without a signed-in operator."],["Follow one request","Browser process creates a request. OS networking passes bytes to a network adapter. Server OS receives the request and wakes a service process. The service reads directory or application data and returns a response."],["Virtual does not mean imaginary","A guest OS has its own logical CPU, memory, disk and adapter allocated by a hypervisor on physical hardware. A virtual domain controller runs the same directory service, subject to supported configuration. A VM checkpoint does not replace an AD-aware backup."]],["Open a Windows training machine or use the examples in this chapter. Identify one process, one service and the resource each uses. Do not change production settings.","Explain why a stopped service, a slow disk and an incorrect password are three different failure classes."],["A domain controller VM boots, but its directory service cannot start because its database disk is full. Which boundary should you investigate first?",["Cloud app consent","Host/guest storage and service event logs","Entra Conditional Access targeting","The user's UPN"],1,"The guest service cannot load its database reliably. Storage and service evidence come before identity policy."],[]],["network","How computers communicate and find services","Infrastructure foundation","Understand a packet, address, port, name and request before learning authentication.","Alex can browse public websites, but the laptop cannot locate its domain controller or reach the cloud sign-in endpoint.",["network","dns"],["cloud"],[],[],["dns","ip-address","http","https-and-tls","api","url","json"],[["Address is not a name","A MAC address is used on the local link, an IP address is used for routing, and a hostname is a readable name resolved by DNS. An IPv4 prefix describes which destinations are local; a gateway routes remote traffic."],["Trace the layers","DHCP provides network settings; DNS finds the endpoint; routing/firewall permit packets; TCP (where used) carries a reliable byte stream; TLS establishes protected transport; HTTP carries application requests. Each layer can fail independently."],["Domain and cloud discovery differ","AD clients need internal SRV service records such as _ldap._tcp.dc._msdcs.contoso.example. Cloud login requires public name resolution and network connectivity. A public DNS resolver can resolve cloud websites but lack private AD records."],["Read the evidence","A 401 or 403 is an HTTP-layer result; receiving it means the request reached an HTTP endpoint. It does not by itself tell whether a directory password, token audience or resource permission was wrong."]],["Interpret ipconfig /all, Resolve-DnsName and Test-NetConnection -Port 443 in the examples. These are read-only checks; an ICMP ping is not the same as a TCP test.","Name the first failing layer before proposing a fix. Explain why successful DNS is not proof of successful sign-in."],["Internal SRV lookup fails using a public resolver, while HTTPS to Microsoft works. Which fix addresses the first failing boundary?",["Grant an Entra admin role","Change token audience","Use the approved AD-aware DNS configuration and verify SRV discovery","Disable MFA"],2,"The evidence concerns internal domain discovery, not cloud authentication or authorization."],[]],["ad","Traditional Active Directory: identity before the cloud","Infrastructure → identity","Understand where an on-premises identity lives and how Windows authenticates it.","Contoso has a domain controller DC1 and a second replica DC2. Alex joins Finance; a file share must be accessible only to authorized employees.",["ad","kerberos","replication","gpo"],[],[],[],["directory-object","object-id","authentication","authorization","security-group","rbac"],[["Directory anatomy","A forest contains domains with shared schema/configuration. Domain controllers hold replicas. An OU organizes objects and can scope administration and GPO application; it is not an access group. A group can carry authorization to a resource."],["One user, several identifiers","Example: DN CN=Alex,OU=Finance,DC=contoso,DC=example; sAMAccountName alex; UPN alex@contoso.example; objectGUID identifies the AD record; SID identifies its Windows security principal. These values are not interchangeable."],["Follow Windows sign-in","Client discovers a DC via DNS. Kerberos authenticates and issues a TGT; a service ticket is requested for an SPN such as cifs/files.contoso.example. File service uses the security context and ACL to decide whether to allow access. LDAP queries directory records; it is not a service ticket."],["Replicas and policy","DC2 can temporarily have older attributes than DC1. AD replication and SYSVOL/DFSR are distinct. Group Policy links and filters determine applicable settings; SMB and NTFS permissions govern resource access."]],["Use the worked DN example to classify its fields. Read the module examples for Get-ADUser, repadmin /replsummary, klist and gpresult /r.","Distinguish a missing AD object, a replication problem, a Kerberos failure, a GPO issue and a file ACL denial."],["Alex exists on DC1 but not DC2, which is the source read by the sync engine. Which action is most evidence-based?",["Create a duplicate cloud account","Verify AD replication and the connector's source replica","Change Alex's source anchor","Grant Finance access to all users"],1,"The sync engine may be reading a stale replica. Fix the source data path before provisioning or permissions."],[]],["tenant","Microsoft 365 and Entra: the cloud organization","SC-300 · user identities","Connect the company, tenant, domains, directory roles, subscriptions and workloads.","Contoso opens Microsoft 365 and wants employees to use contoso.example names, without giving helpdesk administrators control of the whole organization.",[],["tenant"],["tenant-boundary"],["domain-dns"],["tenant","tenant-id","upn","rbac","administrative-unit","role-assignment"],[["Separate the containers","A company is the business; an Entra tenant is its directory/identity boundary; Microsoft 365 workloads use the directory. Azure subscriptions are resource/billing scopes, not the same as the directory. Licenses enable service features, not administrative authority."],["Domain versus tenant","A tenant ID is a GUID, not a domain. The initial onmicrosoft.com domain remains available. A custom domain requires ownership verification with Microsoft's specified DNS record. Changing UPN or mail routing is a separate planned operation."],["Directory privilege versus workload access","An employee can have a license and app assignment without any admin role. A supported administrative-unit scoped role can limit selected directory administration, but an AU does not create a new tenant or scope every possible operation."]],["Use the guided tenant configuration lesson to compare Helpdesk Administrator and Global Administrator; rehearse domain verification without changing actual DNS.","Identify exactly which principal, role, scope and target resource are involved in each grant."],["A regional helpdesk needs password reset authority for employees in one supported administrative unit. What is the narrowest design?",["A whole-tenant Global Administrator role","A Teams membership","A supported directory role scoped to the administrative unit","A Microsoft 365 E5 license alone"],2,"An appropriately scoped directory role grants supported administrative operations; workload entitlement is different."],["portal/roles","portal/units"]],["users","Users, groups, roles and the employee lifecycle","SC-300 · user identities","Understand how identity properties turn into actual effective access and how to remove it.","Alex joins Finance, later moves to IT, then leaves. A partner needs temporary access to a collaboration resource.",[],["objects"],["user-lifecycle","group-app-access","external-b2b"],["custom-attributes","cross-tenant"],["directory-object","object-id","upn","dynamic-membership","security-group","guest-user","b2b-collaboration","cross-tenant-access-settings","application-entitlement","source-of-authority"],[["One record, many relationships","Directory object ID identifies Alex; UPN is a changeable sign-in name. Attributes describe Alex, group membership groups principals, a license enables services, an app assignment grants an entitlement, a resource ACL governs its own actions."],["Joiner, mover, leaver","Create the account with approved attributes; assign the minimum required groups/licenses and app access; verify positive and negative cases. On transfer remove obsolete grants including inherited paths. On departure disable and revoke as appropriate, remove assignments, and verify target access; preserve required data under policy."],["External access","A B2B guest can authenticate using their home identity while the resource tenant controls local permissions and applicable cross-tenant settings. Guest is not synonymous with anonymous access. Tenant trust of MFA or device signals is configurable."],["Effective access can survive one removal","If Alex is assigned Finance directly and via a group, removing only the group is insufficient. Trace both paths. Dynamic group evaluations may not be immediate; verify actual membership and target resource."]],["Configure the joiner workflow in the existing fictional tenant. Include a narrow role and app access, then test a denied unrelated resource.","Demonstrate allowed access, denied unauthorized access and evidence of who changed the grants."],["Alex leaves Finance but can still open Finance Reports after removal from the Finance group. What evidence should you collect?",["Direct assignments and every other inherited access path","Only password age","Only the product license","Only the tenant domain"],0,"Effective access can remain through direct or other group assignments."],["v12/mission/joiner","portal/users","portal/groups"]],["hybrid","Connect traditional AD to Microsoft Entra","SC-300 · hybrid identities","Distinguish synchronization of objects from authentication of users.","Contoso wants an existing AD user to appear in Entra, use their work credentials for cloud apps and retain traditional domain services.",["sync","hybauth"],["hybrid"],["hybrid-sync"],["cloudsync-choice"],["source-of-authority","upn","object-id","authentication","identity-provider"],[["Three independent questions","(1) Which system owns the object/attribute? (2) How are identities provisioned or matched in Entra? (3) Where is the password or other evidence verified? An answer to one does not answer the others."],["Object synchronization","Alex has AD source anchor HYB-A1, UPN alex@contoso.example, and a source OU. Sync evaluates scope, mappings, matching and export. The corresponding Entra record has its own object ID HYB-U1. A cloud object is not a second independent password by definition."],["Compare methods","PHS validates cloud passwords using synchronized derived hashes. PTA validates against AD through available agents. Federation delegates authentication to the configured IdP. Choose using availability, requirements and supported features; PHS is not automatic failover by itself."],["Fault isolation","Missing cloud user: source/replica/scope/export. Present cloud user but password sign-in fails: configured auth method, freshness and agent or IdP evidence. Sign-in success but app blocked: policy or assignment."]],["In the hybrid simulator create Alex in Employees OU, select matching scope, run sync and inspect cloud state. Inject a bad UPN suffix or agent outage, predict the result, then recover.","Explain why a current PHS hash can support a new cloud password sign-in during a modeled on-prem outage while PTA without agents fails."],["The user exists in Entra and PHS is current. An on-prem PTA agent goes down. With PHS configured, what is the modeled new password sign-in outcome?",["Always blocked because every cloud sign-in requires AD","Cloud validation can continue if other cloud controls are satisfied","User must rejoin the domain","An access package must be activated"],1,"PHS cloud validation does not require a live PTA agent for each sign-in."],["v17/lab"]],["device","Device identity, management and compliance","SC-300 · access / MD-102 support","Connect Windows device join, enrollment, compliance and SSO without conflating them.","Alex's laptop is domain joined and Entra hybrid joined, but a cloud application requires compliant devices.",["devices"],[],[],["device-identity"],["device","device-compliance","conditional-access","access-token"],[["Four distinct states","AD domain join is the traditional computer trust. Entra registration commonly represents BYOD; Entra join is cloud join; hybrid join retains AD membership and adds Entra join. None automatically proves Intune enrollment."],["Management and posture","Intune enrollment establishes a management relationship. A compliance policy evaluates device conditions such as supported security settings; applicable results can be consumed by Conditional Access. A device record and a compliant-device result are different."],["Look at concrete fields","dsregcmd /status can show AzureAdJoined, DomainJoined, DeviceId and AzureAdPrt depending on context. Both join flags YES indicate hybrid join in this Windows example; a PRT supports SSO where applicable. Check actual device identity and current compliance separately."],["Follow the decision","User and device evidence reach Entra. An applicable Conditional Access policy may require a compliant device. Correct the failing posture or identity state; do not assume domain membership overrides policy."]],["Use the hybrid simulator to compare registered, joined and hybrid states; enable the fictional strict policy and test noncompliant and compliant configurations.","Explain what each join flag, enrollment and compliance proves—and what it does not."],["A laptop is hybrid joined but Intune reports noncompliance. An enforced policy requires compliant devices. What is the appropriate first action?",["Investigate device compliance details and matching device record","Assume hybrid join meets compliance","Remove every policy","Give the employee an admin role"],0,"Device join and management posture are separate evidence."],["v17/lab","portal/devices"]],["auth","Cloud authentication: credentials, protocols and tokens","SC-300 · authentication","Follow a cloud login from user proof to tokens and distinguish authentication from permission.","Alex signs into a web application using a passkey, then the application calls Microsoft Graph.",[],["auth"],["passwordless-recovery","app-federation"],["sspr"],["authentication","authorization","passkey","fido2","temporary-access-pass","oauth-2-0","openid-connect","saml","id-token","access-token","refresh-token","pkce","jwt"],[["Identity proof","A password is shared-secret evidence; a passkey uses a challenge signed by a private key held by the authenticator, with origin binding. MFA means multiple factors, not two passwords. TAP can bootstrap supported recovery/enrollment under policy."],["Protocol roles","OAuth 2.0 is authorization framework for API access; OIDC adds identity information via an ID token. SAML federation typically supplies assertions to a service provider. These are not interchangeable with Kerberos tickets."],["One sign-in flow","Client sends client ID, redirect URI and requested scopes; PKCE binds an authorization code exchange to its initiator for supported flows. Entra authenticates and evaluates policy; token endpoint returns appropriate tokens. The API verifies issuer, audience, signature, expiry and authorization."],["Field-level example","iss = issuer, aud = target, exp = expiry, scp = delegated scopes, roles = relevant app roles. Claims depend on token type and flow. An ID token for a client is not a Graph access token; decoding a JWT is not signature validation."]],["Work through passwordless recovery and federation lessons, then inspect the existing vocabulary field anatomy for passkey and token.","Describe exactly which actor creates, receives and validates each artifact; distinguish proof from API permission."],["A client authenticates successfully and receives an ID token addressed to the client. It uses that token to call Graph. What should change?",["Use an access token issued for Microsoft Graph with appropriate permissions","Change the tenant display name","Use the ID token after adding the user to an OU","Decode the token and ignore the audience"],0,"The resource requires an appropriate access token, not the client's identity token."],["v15/system/signin","v15/system/passkey","portal/methods"]],["policy","Conditional Access, risk and continuous access","SC-300 · authentication and access","Build policies from scope, signals, controls and evidence rather than memorizing switches.","Contoso wants a pilot group to use strong authentication and compliant devices for sensitive apps.",[],["ca"],["ca-policy","risk-and-logs"],["cae","auth-context","protected-actions","gsa-connectivity"],["conditional-access","policy-scope","grant-control","report-only","what-if","sign-in-risk","user-risk","mfa","authentication-context"],[["Read a policy as a sentence","When this user or workload targets this resource under these conditions, require these controls or block access. Scope, exclusions, conditions, grant controls, session controls and policy state are distinct. Do not mistake a policy for an app entitlement."],["Multiple policies","Applicable enforced policies all matter; an enforced block prevails. Within a grant control, AND/OR configuration matters. Report-only predicts impact without enforcing that policy's grant decision; review actual sign-in results before approved pilot rollout."],["Risk and context","Sign-in risk refers to a particular event; user risk concerns potential account compromise. Authentication strength restricts acceptable proof. Authentication context requires supported app integration for a sensitive operation; a named context alone protects nothing."],["Verify with evidence","Use What If and sign-in logs, then actual permitted and denied tests. Inspect policy results, device ID and authentication details. Keep appropriately protected emergency access and a rollback plan."]],["Open the existing CA masterclass, stateful decision simulator and pilot mission. Start in report-only; identify scope, required controls and evidence; validate authorized pilot before enforcement.","Explain a failed AND grant, a report-only result, an actual block, and a resource permission denial without mixing them."],["A policy requires MFA AND compliant device. The user completes MFA but the device is noncompliant. Policy is report-only. What follows solely from this policy?",["Enforced denial because both controls failed","A predicted grant failure in the report-only result, not an enforced block from that policy","Successful grant because MFA overrides compliance","Automatic removal from the pilot group"],1,"Both requirements are not satisfied, but report-only does not enforce this policy's grant decision."],["v7/ca-masterclass","v7/ca-simulator","v12/mission/pilot"]],["apps","Applications, API permissions and workload identities","SC-300 · workload identities","Understand which object represents software and where authorization is granted.","Contoso has a payroll web app, a SaaS enterprise app and an Azure workload that must read a secret without storing a credential.",[],["workloads"],["app-consent","managed-workload","scim-monitoring"],["app-proxy","scim-provisioning","defender-cloud-apps"],["application-registration","enterprise-application","service-principal","managed-identity","delegated-permission","application-permission","consent","scope","microsoft-graph","scim-provisioning"],[["Two records, different jobs","App registration describes the application in its home tenant: client ID, redirect URIs, supported accounts and requested permissions. A service principal is the application's tenant-local identity. Enterprise applications manage tenant-local assignments, SSO and other settings."],["Delegated versus application","Delegated access acts with a signed-in user under granted scopes and user rights. Application-only access operates without a user under application permissions or resource roles. Consent is not identical to a user assignment or a Key Vault data-plane permission."],["Managed identity","An Azure-supported workload can request a token without storing its own secret. The service principal still needs narrow resource-level authorization. A token for Graph is not a Key Vault token."],["Provisioning is separate","SSO authenticates; SCIM provisioning creates, updates or deprovisions accounts in supported target apps. App proxy publishes supported on-prem apps through connectors; it is not a replacement for app authorization."]],["Run the workload mission, trace app registration and enterprise application, and verify one permitted API/resource action and one denied action.","Explain which IDs identify software, tenant-local principal and resource, and how least-privilege permissions differ by API."],["An Azure app has a managed identity and receives a Key Vault token, but reading a secret is denied. What should be inspected?",["Only the application display name","The Key Vault authorization configuration and scoped data permissions","The user's Outlook license","Only the DNS TXT domain record"],1,"Managed identity and token issuance establish identity; the resource must authorize the operation."],["v12/mission/workload","portal/apps","v15/system/managed"]],["govern","Govern access over time and privilege","SC-300 · governance","Make access temporary, reviewed and traceable rather than permanent.","A contractor needs access to Project Alpha for 30 days; a security admin needs elevated authority only during approved work.",[],["governance"],["governance-package","pim-operations"],["entitlement-tou","pim-groups"],["access-package","privileged-identity-management","eligible-role","role-activation","access-review","joiner","source-of-authority","rbac"],[["Resource entitlement versus administrator privilege","An access package bundles resource roles and request/assignment policy. PIM governs eligible or time-limited privileged roles/groups. Access reviews periodically decide whether existing access remains appropriate."],["One contractor lifecycle","Request scoped package; sponsor approves; assignments grant specific resource roles; expiry or review removes those package-granted roles. Inspect actual resource access and alternate direct grants; an expired package alone does not prove every access path disappeared."],["One privileged operation","Eligible role is potential authority. Activation creates time-limited active authority under configured approval, justification and authentication controls. Audit who activated, when, scope and whether the role expired. Use separate emergency access and appropriate licensing."],["Governance evidence","Lifecycle workflows automate selected joiner/mover/leaver tasks. Review configuration and target outcomes, not just the workflow label. A request policy does not automatically correct an unrelated direct assignment."]],["Complete the contractor mission and PIM guided exercises. Test approved project access and unrelated resource denial, then verify removal.","Explain eligibility vs active authority, package assignment vs actual permissions, and review vs revocation."],["An administrator is eligible for a privileged role but has not activated it. A contractor's access package is active. Which statement is correct?",["Both automatically hold the same admin permissions","The package grants all tenant roles","Eligibility alone is not active role authority; package grants configured resources","PIM replaces resource permissions"],2,"PIM privilege and governed resource assignment are distinct."],["v12/mission/contractor","portal/pim","portal/packages"]],["workloads","Microsoft 365 workloads and Zero Trust","SC-900 / SC-300 integration","Connect Exchange, Teams, SharePoint, Intune, Defender and Purview to the identity foundation.","Alex can sign in to Teams but cannot open a channel file; Outlook desktop repeatedly prompts for credentials.",["security"],["m365"],[],[],["conditional-access","authorization","device-compliance","sign-in","audit-log"],[["Service map","Entra supplies identity and policy; Exchange hosts mail/calendar; SharePoint hosts sites and documents; OneDrive stores user files on SharePoint infrastructure; Teams collaboration uses other workloads including SharePoint for files. Intune manages devices. Defender detects/protects; Purview protects and governs data."],["License versus authorization","A license may enable Exchange or Teams; mailbox delegation, team membership, SharePoint site/item permissions and sharing control access. Successful sign-in does not prove resource permission."],["Trace an actual issue","Teams channel file denial: identify target SharePoint resource, check user membership/sharing and policy. Outlook web works but desktop prompts: compare client type, device and policy result in the sign-in logs; then investigate token/client state."],["Hybrid security","Protect on-prem privileged paths, connectors, certificates and cloud administrators. Design independent recovery paths and test approved recovery. Zero Trust means verify explicitly, least privilege and assume breach, not trust every domain-joined device."]],["Use the diagnostic casebooks, then compare results with the official SC-900 fundamentals learning and SC-300 study guide.","Separate identity, device, workload, data security and service-health failures in your explanation."],["Teams sign-in succeeds but a channel document is denied. Which investigation is most directly relevant?",["Rebuild all domain controllers","Inspect the associated SharePoint permissions, sharing and relevant policy","Change every employee's UPN","Reset all passwords"],1,"Teams files can depend on SharePoint resource permissions and policy."],["v16/cases","v17/cases"]],["ops","Administration, evidence and troubleshooting","SC-300 · all domains","Learn how to investigate and automate without confusing a symptom with its cause.","A user reports access denied after a role change. The helpdesk must identify the failure from logs and verify the fix.",["diagnose"],["automation","troubleshoot"],[],["bulk-automation","diagnostic-kql"],["microsoft-graph","api","json","http-403","audit-log","sign-in","correlation-id","kql"],[["Choose the correct evidence","Sign-in logs describe authentication and applicable access decisions; audit logs record supported administrative changes; provisioning logs describe provisioning operations. The same UPN can appear in different events; collect timestamp, tenant, resource and correlation ID."],["Read before writing","Use approved read-only Graph or PowerShell permissions, select the correct tenant and object ID, follow pagination, handle throttling. Exported logs can be queried using KQL where configured. A successful API call is not proof the business operation works."],["Concrete read","Get-MgUser -UserId <object-id> -Property Id,UserPrincipalName,AccountEnabled reads selected user fields with required Graph access. A sample Log Analytics query: SigninLogs | where ResultType != '0' | project TimeGenerated, UserPrincipalName, AppDisplayName, ResultType. Requires configured export and supported schema."],["Diagnose systematically","Scope one user vs many, one device vs many, one service vs all. Find first failing boundary: network → directory → sync → auth → policy → resource. Fix the smallest verified cause, retest original and negative actions, document and escalate when needed."]],["Complete casebooks and diagnostic clinics. Write a short incident record including affected identity, timestamp, failure layer, corrective action and verified result.","Do not equate a green service status, a sign-in success or a single API response with end-to-end business success."],["An audit shows a group membership was changed yesterday, but a user's current sign-in fails a compliant-device grant. Which evidence best identifies the immediate sign-in failure?",["The historic membership event alone","Current sign-in event and relevant device compliance evidence","The application name only","The subscription billing record"],1,"Current sign-in/device evidence addresses the observed grant failure; audit history is useful context but does not alone prove the cause."],["v17/cases","v16/cases","portal/logs"]],["capstone","End-to-end enterprise practice and exam preparation","SC-300 certification integration","Prove you can connect all layers, not just recognize terms.","Contoso hires Alex into Helpdesk, synchronizes the account, requires a compliant device, authorizes one application, investigates a failure and offboards Alex.",["capstone"],["mastery"],[],[],["authentication","authorization","conditional-access","access-package","privileged-identity-management","audit-log"],[["First draw the architecture","State the source directory, sync method, authentication method, cloud identity, device state, policy, entitlement and resource decision. Label where evidence lives. Cloud-only tenants do not need on-prem AD; this capstone intentionally models hybrid."],["Then configure and verify","Create scoped source identity and sync; validate cloud record; set approved device/policy/app assignments; prove Helpdesk allowed and Finance denied; inject and diagnose an outage; disable source account, sync and verify denied new sign-in. Real revocation/session behavior is more complex."],["Then demonstrate breadth","Complete the existing connected identity, authentication, workload and governance missions in independent mode. Review Microsoft's official current objective list, practice assessments and labs. The academy's fictional state is not an actual Microsoft tenant."],["Use errors to learn","Study mistakes by objective, reconstruct the flow in your own words, then attempt fresh unseen scenarios. Do not treat repeated quiz success, reading completion or self-review as proof of passing a certification."]],["Complete the hybrid lab plus the four existing connected missions. Use the objective tracker, official study guide and existing exam simulator for a fresh assessment.","Record separate evidence for concept checks, simulated practical work and authorized real-world verification; no automatic certification guarantee."],["Which evidence is strongest for readiness after completing the course?",["A self-reported read-through","Repeated memorized answers only","An independent fresh objective-balanced assessment plus validated practical tasks and reviewed gaps","A green simulated deployment status"],2,"Transfer to fresh tasks and objective-aligned practice is stronger evidence; actual exam performance is not guaranteed."],["v17/lab","v12/missions","objectives","v7/advanced-exam","exams"]]];
const v16=window.__V16_TESTS,v17=window.__V17_TESTS,v15=window.__V15_TESTS;
const deep=V8_LESSONS,clinics=[...V11_CLINICS_A,...V11_CLINICS_B];
const H=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
const P=x=>'<p>'+H(x)+'</p>';
const B=(r,t)=>'<button class="btn" data-route="'+H(r)+'">'+H(t)+'</button>';
const A=(url,t)=>'<a href="'+H(url)+'" rel="noopener noreferrer" target="_blank">'+H(t)+'</a>';
const sec=(t,b)=>'<section class="un-card"><h3>'+H(t)+'</h3>'+b+'</section>';
const detail=(t,b,open=false)=>'<details class="un-detail" '+(open?'open':'')+'><summary>'+H(t)+'</summary><div class="un-detail-body">'+b+'</div></details>';
const key='entra-unified-v1';
let s={chapter:curriculum[0][0],answers:{},notes:{},opened:{}};try{const x=JSON.parse(localStorage.getItem(key)||'null');if(x&&typeof x==='object')s={...s,...x};}catch(e){}
function persist(){try{localStorage.setItem(key,JSON.stringify(s));}catch(e){toast('Local progress could not be saved.');}}
const css='<style>.un-course{max-width:1120px;margin:auto;color:inherit}.un-course h1,.un-course h2,.un-course h3{line-height:1.25}.un-kicker{font-size:12px;letter-spacing:.075em;text-transform:uppercase;color:#1268a9;font-weight:750}.un-card{border:1px solid #b8c9dc;border-radius:13px;padding:18px;margin:14px 0;background:var(--panel,#fff);color:var(--text,#15263a)}.un-card h3{margin:0 0 9px}.un-card p,.un-card li,.un-detail p,.un-detail li{line-height:1.7}.un-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:10px}.un-grid .un-card{margin:0}.un-detail{margin:10px 0;border:1px solid #cbd6e3;border-radius:9px;overflow:hidden;background:var(--panel,#fff);color:var(--text,#15263a)}.un-detail summary{cursor:pointer;font-weight:700;padding:13px;background:#eaf2fa;color:#173d62}.un-detail-body{padding:13px 16px}.un-course .btn{white-space:normal;margin:4px 4px 4px 0}.un-course textarea{width:100%;min-height:105px;box-sizing:border-box;padding:12px}.un-result{border-left:4px solid #1e76be;background:#e8f3ff;color:#153c61;padding:12px;margin:12px 0}.un-choices .btn{display:block;width:100%;text-align:left;box-sizing:border-box}.un-top{display:flex;gap:12px;flex-wrap:wrap;align-items:center}.un-top>div{flex:1;min-width:200px}.un-num{font-size:24px;font-weight:750}.un-row{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:12px;border-bottom:1px solid #d8e1eb}.un-row>div{flex:1;min-width:185px}.un-row b{display:block}.un-progress{height:9px;border-radius:10px;background:#dce7f1;overflow:hidden}.un-progress span{display:block;height:100%;background:#0078d4}.un-bridge{margin:12px 16px;padding:12px;border:1px solid #b8c9dc;border-radius:10px;background:#eaf2fa;color:#173d62}.un-library{padding:8px}.un-library summary{font-weight:650;cursor:pointer;padding:8px}.un-course a{overflow-wrap:anywhere}.un-course ol{padding-left:24px}.un-course code{white-space:normal;overflow-wrap:anywhere}</style>';
const chapter=id=>curriculum.find(c=>c[0]===id);
const croute=c=>'course/chapter/'+c[0];
const rows17=c=>c[5].map(id=>v17.lessons.find(l=>l[0]===id)).filter(Boolean);
const rows16=c=>c[6].map(id=>v16.data.lessons.find(l=>l[0]===id)).filter(Boolean);
const rows8=c=>c[7].map(id=>deep.find(l=>l.id===id)).filter(Boolean);
const rows11=c=>c[8].map(id=>clinics.find(l=>l.id===id)).filter(Boolean);
const vocab=c=>{
 const out=new Map(),add=(name,definition,source)=>{const id=String(name).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!out.has(id))out.set(id,{name,definition,source,id});};
 for(const l of rows17(c))for(const t of l[5])add(t[0],t[1],l[3]);
 for(const l of rows16(c))for(const t of l[6])add(t[0],t[1],l[4]);
 for(const id of c[9]){const t=v15.get(id);if(t)add(t.term,t.definition,t.source);}
 return [...out.values()].map(x=>({...x,full:v15.get(x.id)}));
};
const qset=c=>{
 const q=[];
 // Each reused question remains one distinct source question. The final synthesis is independently authored.
 for(const l of rows17(c))q.push({id:'h-'+l[0],question:l[9],options:l[10],correct:l[11],why:l[12]});
 for(const l of rows16(c))for(let i=0;i<2;i++){const z=l[11+i];q.push({id:'e-'+l[0]+'-'+i,question:z[0],options:z[1],correct:z[2],why:z[3]});}
 for(const l of rows8(c))q.push({id:'d-'+l.id,question:l.q,options:l.choices,correct:l.answer,why:l.feedback});
 for(const l of rows11(c))q.push({id:'a-'+l.id,question:l.incident+' What is the best first decision?',options:l.options,correct:l.correct,why:l.diagnosis});
 const z=c[12];q.push({id:'synthesis',question:z[0],options:z[1],correct:z[2],why:z[3]});
 return q.filter(x=>typeof x.question==='string'&&Array.isArray(x.options)&&x.options.length>=2&&Number.isInteger(x.correct)&&x.correct>=0&&x.correct<x.options.length);
};
function status(c){const q=qset(c),correct=q.filter(x=>s.answers[c[0]+':'+x.id]===x.correct).length;return {correct,total:q.length,done:correct===q.length,notes:!!s.notes[c[0]]};}
function recommendation(){return curriculum.find(c=>!status(c).done)||curriculum.at(-1);}
function progress(){return curriculum.reduce((a,c)=>{const x=status(c);a.correct+=x.correct;a.total+=x.total;a.done+=Number(x.done);return a;},{correct:0,total:0,done:0});}
const oldRender=render,oldShell=shell,oldAction=action;
const nav=(r,label)=>'<button class="navitem '+(current()===r?'active':'')+'" data-route="'+H(r)+'">'+H(label)+'</button>';
shell=(content,where)=>{
 let html=oldShell(content,where);
 const side=/<aside class="side fluent-side" id="side">([\s\S]*?)<\/aside>/;
 html=html.replace(side,(all,inside)=>{
  const start=inside.indexOf('<div class="sectioncap">Administration</div>'),end=inside.indexOf('<div class="sidefoot">');
  if(start<0||end<start)return all;
  const original=inside.slice(start,end),adminEnd=original.indexOf('<div class="sectioncap">Your training</div>');
  const admin=adminEnd>=0?original.slice(0,adminEnd):'';
  const library=adminEnd>=0?original.slice(adminEnd):original;
  return '<aside class="side fluent-side" id="side">'+inside.slice(0,start)+'<div class="sectioncap">One learning journey</div>'+nav('course/home','▣ Start / continue learning')+nav('course/chapters','▤ Complete curriculum')+nav('course/recall','◇ Recall and review')+nav('course/practice','⚑ Practice and assessments')+nav('course/evidence','☷ My learning evidence')+(where.startsWith('portal/')?admin:'<details class="un-library"><summary>Admin practice console</summary>'+admin+'</details>')+'<details class="un-library"><summary>Reference and earlier tools</summary>'+library+'</details>'+inside.slice(end)+'</aside>';
 });
 html=html.replace('data-route="missions" title="Guided missions"','data-route="course/practice" title="Practice and assessments"');
 html=html.replace('data-route="missions">Guide me','data-route="course/home">Continue learning');
 if(!where.startsWith('course/')){let c=chapter(s.chapter)||recommendation();html=html.replace(/(<main id="view"[^>]*>)/,'$1'+css+'<div class="un-bridge"><b>Learning journey · '+H(c[1])+'</b> '+B(croute(c),'Return to current chapter')+B('course/home','Course home')+'</div>');}
 return html;
};
function layout(body){return '<div class="page un-course">'+css+body+'</div>';}
function intro(){const x=progress(),next=recommendation(),last=chapter(s.chapter)||next;return layout('<div class="un-kicker">Ultimate Microsoft identity learning and training · SC-300 first</div><h1>One connected learning journey</h1>'+P('Start with computers and networks, then learn Active Directory, Microsoft 365, cloud identity, authentication, access, applications, governance and troubleshooting. You do not need to choose among competing learning paths.')+sec('Your next step','<div class="un-top"><div><div class="un-num">'+x.done+' / '+curriculum.length+'</div>chapters with every concept check correct</div><div><div class="un-num">'+x.correct+' / '+x.total+'</div>current correct answers</div></div><div class="un-progress"><span style="width:'+(x.total?100*x.correct/x.total:0)+'%"></span></div>'+P('Recommended next chapter: '+next[1])+B(croute(next),'Continue in order →')+B(croute(last),'Resume last opened chapter')+P('Correct answers are learning evidence only; independent practical and real-tenant evidence are separate.'))+'<h2>What every chapter teaches</h2><div class="un-grid">'+[['Understand','Vocabulary before jargon; what it is, what it does, why and when it exists.'],['Trace','Follow a concrete business request across systems and identify each input, output and decision.'],['Practice','Use the relevant existing simulator at the point where it makes sense.'],['Prove','Answer concept and scenario questions, explain your reasoning and validate allowed/denied outcomes.']].map(x=>sec(x[0],P(x[1]))).join('')+'</div>'+sec('Your entire curriculum',chapterList()+B('course/chapters','View chapter list'))+sec('Certification scope',P('SC-300 is the primary certification. Infrastructure, Microsoft 365, SC-900, Intune and security topics support it; they are not separate required routes through the course. The official study guide is the authoritative objective list.')+'<p>'+A('https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-300','Microsoft SC-300 study guide')+'</p>'));}
function chapterList(){return curriculum.map((c,i)=>{const x=status(c);return '<div class="un-row"><div><div class="un-kicker">Chapter '+(i+1)+' · '+H(c[2])+'</div><b>'+H(c[1])+'</b>'+H(c[3])+'</div><div style="flex:0 1 auto;min-width:120px"><span>'+x.correct+' / '+x.total+' checks'+(x.done?' ✓':'')+'</span> '+B(croute(c),x.done?'Review':'Learn')+'</div></div>';}).join('');}
function chapterIndex(){return layout('<h1>Complete curriculum</h1>'+P('Study in this order. Review any chapter freely; previously saved progress remains available.')+chapterList());}
function vdetail(t){let b=P(t.definition);if(t.full){const f=t.full;b+='<p><b>What it does:</b> '+H(f.does)+'</p><p><b>Why:</b> '+H(f.why)+'</p><p><b>When:</b> '+H(f.when)+'</p><p><b>How:</b> '+H(f.how)+'</p><p><b>Micro:</b> '+H(f.micro)+'</p><p><b>System relationship:</b> '+H(f.macro)+'</p><p><b>Common failure:</b> '+H(f.failure)+'</p>'+B('v15/term/'+f.id,'Open field anatomy / full term');}const anatomy=typeof V15_ANATOMY!=='undefined'?V15_ANATOMY.find(a=>a[0]===t.id):null;if(anatomy)b+='<h4>Field-by-field anatomy</h4><div class="un-result"><code>'+H(anatomy[1])+'</code></div>'+pairs(anatomy[2])+P(anatomy[3]);if(t.source)b+='<p>'+A(t.source,'Technical reference')+'</p>';return '<div class="un-card"><h3>'+H(t.name)+'</h3>'+P(t.definition)+detail('Why / when / how · technical depth',b)+'</div>';}
function ordered(items){return '<ol>'+items.map(x=>'<li>'+H(x)+'</li>').join('')+'</ol>';}
function pairs(items){return '<ol>'+items.map(x=>'<li><b>'+H(x[0])+'</b> — '+H(x[1])+'</li>').join('')+'</ol>';}
function h17(l){return detail(l[1],P(l[4])+'<h4>System sequence</h4>'+ordered(l[6])+'<h4>Concrete example</h4>'+P(l[7])+'<h4>Diagnose</h4>'+P(l[8])+'<p>'+A(l[3],'Official technical reference')+'</p>');}
function e16(l){return detail(l[1].replace(/^\d+\s*·\s*/,''),P(l[7])+'<h4>System sequence</h4>'+ordered(l[8])+'<h4>Concrete example</h4>'+P(l[9])+'<h4>Diagnose</h4>'+P(l[10])+'<p>'+A(l[4],'Official technical reference')+'</p>');}
function d8(l){return detail(l.title,P(l.objective)+P(l.beginner)+P(l.technical)+'<h4>Trace the architecture</h4>'+pairs(l.visual)+'<h4>Guided administration</h4><ol>'+l.steps.map(x=>'<li><b>'+H(x[0])+'</b>'+P(x[2])+P(x[3])+B(x[1],'Open related admin screen')+'</li>').join('')+'</ol><h4>Worked failure</h4>'+P(l.symptom)+P(l.reason)+P(l.recover)+'<h4>Evidence to produce</h4>'+P(l.evidence)+'<p>'+A(l.docs,'Microsoft reference')+'</p>'+B('v8/learn/'+l.id,'Open original interactive guided exercise'));}
function c11(l){return detail(l.topic,P(l.intro)+P(l.tech)+P(l.why)+'<h4>Configuration path</h4>'+P(l.path)+P(l.level)+'<h4>Trace the system</h4>'+pairs(l.visual)+'<h4>Hands-on sequence</h4>'+pairs(l.guided)+'<h4>Failure and diagnosis</h4>'+P(l.incident)+P(l.diagnosis)+'<h4>Practice and verification</h4>'+P(l.practice)+P(l.evidence)+'<p>'+A(l.src,'Microsoft technical reference')+'</p>'+B('v11/clinic/'+l.id,'Open original advanced exercise'));}
function question(c,q,i){const a=s.answers[c[0]+':'+q.id];return detail('Check '+(i+1)+' · '+(a===q.correct?'Correct':Number.isInteger(a)?'Review needed':'Not attempted'),P(q.question)+'<div class="un-choices">'+q.options.map((t,j)=>'<button class="btn '+(a===j?'primary':'')+'" data-action="un-answer" data-chapter="'+H(c[0])+'" data-id="'+H(q.id)+'" data-value="'+j+'">'+H(t)+'</button>').join('')+'</div>'+(Number.isInteger(a)?'<div class="un-result"><b>'+(a===q.correct?'Correct':'Not yet')+'</b>'+P(q.why)+'</div>':''),Number.isInteger(a)||i===0);}
const labels={"portal/roles":"Directory roles","portal/units":"Administrative units","portal/users":"User records","portal/groups":"Groups","portal/devices":"Device records","portal/methods":"Authentication methods","portal/apps":"Enterprise applications","portal/pim":"Privileged Identity Management","portal/packages":"Access packages","portal/logs":"Sign-in and audit logs","v12/mission/joiner":"Employee onboarding mission","v12/mission/pilot":"Conditional Access pilot mission","v12/mission/workload":"Workload identity mission","v12/mission/contractor":"Contractor governance mission","v12/missions":"Connected Entra missions","v17/lab":"Hybrid identity simulator","v17/cases":"Hybrid diagnostic scenarios","v16/cases":"Microsoft 365 diagnostic scenarios","v15/system/signin":"Sign-in system walkthrough","v15/system/passkey":"Passkey field walkthrough","v15/system/managed":"Managed identity walkthrough","v7/ca-masterclass":"Conditional Access masterclass","v7/ca-simulator":"Conditional Access decision simulator","v7/advanced-exam":"Advanced exam practice","objectives":"Exam objective tracker","exams":"Exam simulator"};
function chapterPage(c){const i=curriculum.indexOf(c),st=status(c),words=vocab(c),qs=qset(c);return layout(B('course/home','← Course home')+'<div class="un-kicker">Chapter '+(i+1)+' of '+curriculum.length+' · '+H(c[2])+'</div><h1>'+H(c[1])+'</h1>'+P(c[3])+sec('Business situation',P(c[4]))+'<h2>1 · Vocabulary — learn the building blocks</h2>'+P('Open a term whenever you cannot explain it. The full microscope expands the exact mechanism, purpose, dependencies and common failures when available.')+'<div class="un-grid">'+words.map(vdetail).join('')+'</div><h2>2 · Understand the whole system</h2>'+c[10].map((z,n)=>sec((n+1)+'. '+z[0],P(z[1]))).join('')+'<h2>3 · Technical depth, configuration and worked examples</h2>'+P('These related lessons are integrated here. You do not need to jump between academy versions to read them. Open each subsection in order for the detail and practical evidence.')+rows17(c).map(h17).join('')+rows16(c).map(e16).join('')+rows8(c).map(d8).join('')+rows11(c).map(c11).join('')+'<h2>4 · Apply what you learned</h2>'+sec('Concrete practice assignment',P(c[11][0])+P(c[11][1])+c[13].map(r=>B(r,labels[r]||r)).join('')+P('Use fictional data only unless you have explicit permission for a real lab. The academy does not provision Azure or Microsoft 365 resources.'))+'<h2>5 · Check understanding</h2>'+P(st.correct+' of '+st.total+' current answers correct. These are learning checks with feedback, not an independent exam.')+qs.map((q,n)=>question(c,q,n)).join('')+'<h2>6 · Teach it back and prove it</h2>'+sec('Write your own explanation','<p>Explain the exact components, their inputs and outputs, what changes state, what fails and how you verify the result. A saved explanation is self-reported evidence, not automatically graded mastery.</p><form id="un-notes" data-id="'+H(c[0])+'"><textarea name="notes" aria-label="Your chapter explanation">'+H(s.notes[c[0]]||'')+'</textarea><button class="btn primary" type="submit">Save explanation</button></form>')+sec('Continue in order',P(st.done?'All chapter concept checks are currently correct. Complete the practice assignment before treating this as learned.':'Revisit incorrect checks and explain the reasons. You may move ahead, but the course will recommend the earliest incomplete chapter.')+(i?B(croute(curriculum[i-1]),'← Previous chapter'):'')+(i<curriculum.length-1?B(croute(curriculum[i+1]),'Next chapter →'):B('course/practice','Independent practice and assessment'))));}
function recall(){const c=chapter(s.chapter)||recommendation(),x=progress();return layout('<h1>Recall and review</h1>'+P('Study the terms at the point you encounter them, then use spaced recall. Prioritize missed checks rather than reading every path again.')+sec('Current chapter: '+c[1],vocab(c).map(vdetail).join('')+B(croute(c),'Return to chapter'))+sec('Targeted revision',curriculum.filter(c=>!status(c).done).map(c=>'<p>'+H(c[1])+' · '+status(c).correct+'/'+status(c).total+' '+B(croute(c),'Review checks')+'</p>').join('')+P(x.done===curriculum.length?'All current concept checks correct; use independent assessment.':'Start with the earliest incomplete chapter.'))+sec('Full recall tools',B('v17/cards','Spaced recall flashcards')+B('v15/vocabulary','Search all identity vocabulary')+B('v15/systems','Visual system reference')));}
function practice(){return layout('<h1>Practice and assessments</h1>'+P('Use these tools after the related chapter. They are exercises inside the same learning journey, not competing courses.')+curriculum.filter(c=>c[13].length).map(c=>sec(c[1],P(c[11][0])+c[13].map(r=>B(r,labels[r]||r)).join(''))).join('')+sec('Official certification preparation','<p>'+A('https://learn.microsoft.com/en-us/credentials/certifications/resources/study-guides/sc-300','Current official objectives')+' · '+A('https://microsoftlearning.github.io/SC-300-Identity-and-Access-Administrator/','Official practical lab instructions')+'</p>'+B('objectives','Objective tracker')+B('exams','Existing exam bank')+B('v7/advanced-exam','Advanced independent practice')+P('Real labs may require an authorized licensed tenant. No simulation score guarantees exam success.')));}
function evidence(){const x=progress(),engine=window.__V12_TESTS,missions=['joiner','pilot','workload','contractor'];let state=missions.map(id=>{let m=engine?.getMission(id),a=engine?.getAttempt(id);let valid=!!(m&&a?.submitted&&engine.stillValid(m,a));return '<li>'+H(id)+': '+H(valid&&a?.mode==='exam'&&a?.knowledge?'independent modeled criteria currently met':valid?'modeled configuration criteria currently met':'not currently verified')+'</li>';}).join('');let lab=window.__V17_TESTS.state.lab,ok=window.__V17_TESTS.criteria(lab).every(z=>z[1]);return layout('<h1>My learning evidence</h1>'+sec('Concept understanding',P(x.correct+' / '+x.total+' current correct answers; '+x.done+' / '+curriculum.length+' chapters have all checks correct.')+P('Prior learning records are preserved: V16 '+v16.score()+' correct concept answers; V17 '+v17.lessons.filter(l=>v17.state.answers[l[0]]===l[11]).length+' correct lesson checks. These are not automatically credited as new chapter checks.')+chapterList())+sec('Practical evidence (existing state)',P('Hybrid onboarding criteria currently '+(ok?'met':'not met')+'.')+'<ul>'+state+'</ul>'+B('course/practice','Open practical exercises'))+sec('Local reflections',curriculum.filter(c=>s.notes[c[0]]).map(c=>detail(c[1],P(s.notes[c[0]]))).join('')+P('Notes are self-reported and not scored.'))+sec('Backup and certification limits','<button class="btn" data-action="un-export">Export unified learning progress</button>'+B('notes','Existing academy backup and progress')+P('The unified export includes unified chapter answers and reflections plus copies of V16 and V17 local learning state. The existing academy has its own export. This does not certify exam readiness or real tenant competency.')));}
render=()=>{const r=current();if(['home','learn','v14/path','v16/home','v17/home'].includes(r)){location.hash='#/course/home';return render();}if(!r.startsWith('course/')){oldRender();return;}let out;if(r==='course/home')out=intro();else if(r==='course/chapters')out=chapterIndex();else if(r==='course/recall')out=recall();else if(r==='course/practice')out=practice();else if(r==='course/evidence')out=evidence();else if(r.startsWith('course/chapter/')){let c=chapter(r.split('/').at(-1));if(c){s.chapter=c[0];s.opened[c[0]]=true;persist();out=chapterPage(c);}else out=chapterIndex();}else out=intro();$('root').innerHTML=shell(out,r);document.title='Microsoft Identity Academy · One learning journey';lastRenderedHash=location.hash;};
action=(name,el)=>{const d=el?.dataset||{};if(name==='un-answer'){const c=chapter(d.chapter),q=c&&qset(c).find(x=>x.id===d.id),v=Number(d.value);if(q&&Number.isInteger(v)&&v>=0&&v<q.options.length){const opened=typeof document.querySelectorAll==='function'?[...document.querySelectorAll('.un-course details')].map(d=>d.open):[],y=window.scrollY||0;s.answers[c[0]+':'+q.id]=v;persist();render();if(typeof document.querySelectorAll==='function'){[...document.querySelectorAll('.un-course details')].forEach((d,i)=>{if(opened[i])d.open=true;});}if(typeof window.scrollTo==='function')window.scrollTo(0,y);}return;}if(name==='un-export'){downloadText('unified-identity-learning.json',JSON.stringify({schema:'unified-identity-learning-v1',exportedAt:new Date().toISOString(),unified:s,engineering:v16.state,hybrid:v17.state},null,2));return;}oldAction(name,el);};
document.addEventListener('submit',e=>{if(e.target?.id!=='un-notes')return;e.preventDefault();if(chapter(e.target.dataset.id)){s.notes[e.target.dataset.id]=String(new FormData(e.target).get('notes')||'').slice(0,12000);persist();toast('Chapter explanation saved locally.');}});
function audit(){const checks=[],check=(name,pass)=>checks.push({name,pass:!!pass});const ids=(n)=>curriculum.flatMap(c=>c[n]);check('14 chapters and unique IDs',curriculum.length===14&&new Set(curriculum.map(c=>c[0])).size===14);for(const [n,source] of [[5,v17.lessons.map(l=>l[0])],[6,v16.data.lessons.map(l=>l[0])],[7,deep.map(l=>l.id)],[8,clinics.map(l=>l.id)]]){const a=ids(n);check('Every source lesson mapped once: '+n,a.length===source.length&&new Set(a).size===a.length&&source.every(id=>a.includes(id)));}for(const c of curriculum){let q=qset(c);check(c[0]+' has learning content',vocab(c).length>=3&&q.length>=2&&c[10].length>=3&&q.some(x=>x.id==='synthesis'));check(c[0]+' question IDs unique',new Set(q.map(x=>x.id)).size===q.length);let html=chapterPage(c);check(c[0]+' complete render',['Vocabulary','Understand the whole system','Technical depth','Apply what you learned','Check understanding','Teach it back'].every(x=>html.includes(x)));check(c[0]+' all source material embedded',rows17(c).every(l=>html.includes(H(l[7])))&&rows16(c).every(l=>html.includes(H(l[9])))&&rows8(c).every(l=>html.includes(H(l.technical)))&&rows11(c).every(l=>html.includes(H(l.tech))));}check('home renders ordered path',intro().includes('One connected learning journey')&&intro().includes('Continue in order'));check('recall renders',recall().includes('Recall and review'));check('practice renders',practice().includes('Practice and assessments'));check('evidence renders',evidence().includes('Practical evidence'));const failed=checks.filter(x=>!x.pass);return {chapters:curriculum.length,integratedSourceLessons:ids(5).length+ids(6).length+ids(7).length+ids(8).length,questions:progress().total,passed:checks.length-failed.length,failed:failed.length,failures:failed,testType:'source and simulated render; not actual browser or real tenant'};}
window.__UNIFIED_TESTS={audit,curriculum,qset,status,progress,vocab,chapterPage,state:s};
})();